contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seed, uint256 amount) public payable {
        require(amount <= address(this).balance, "not enough balance");

        c.seedMarket{value: seed}(seed);

        uint256 marketBefore = c.marketDrugs();
        uint256 balanceBefore = address(c).balance;

        uint256 expectedBought = c.calculateDrugBuy(amount, balanceBefore - amount);
        uint256 expectedFee = c.devFee(expectedBought);
        uint256 expectedClaimedIncrease = expectedBought - expectedFee;

        uint256 claimedBefore = c.claimedDrugs(address(this));

        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 claimedAfter = c.claimedDrugs(address(this));

        assert(!reverted && claimedAfter - claimedBefore == expectedClaimedIncrease);
    }

    receive() external payable {}
}

