contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seedDrugs, address ref) public payable {
        require(seedDrugs <= address(this).balance);

        c.seedMarket{value: seedDrugs}(seedDrugs);
        c.getFreeKilo();

        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 refClaimedBefore = c.claimedDrugs(ref);
        uint256 marketBefore = c.marketDrugs();

        uint256 drugsUsed = c.getMyDrugs();

        c.collectDrugs(ref);

        uint256 refClaimedAfter = c.claimedDrugs(ref);
        uint256 marketAfter = c.marketDrugs();
        uint256 claimedAfter = c.claimedDrugs(address(this));

        assert(
            ref == address(this)
            ? refClaimedAfter >= refClaimedBefore
            : refClaimedAfter == refClaimedBefore + drugsUsed / 5
        );
        assert(marketAfter == marketBefore + drugsUsed / 10);
        assert(claimedAfter == 0);
    }

    receive() external payable {}
}

